const {chromium}=require('playwright');const assert=require('node:assert/strict');const fs=require('node:fs');
(async()=>{fs.mkdirSync('work/screenshots',{recursive:true});const browser=await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox']});
const errors=[];const context=await browser.newContext({viewport:{width:1440,height:1100}});const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});
await page.goto('http://127.0.0.1:8765/',{waitUntil:'networkidle'});assert.equal(await page.locator('#renderError').isVisible(),false,'WebGL initializes');await page.screenshot({path:'work/screenshots/01-desktop.png',fullPage:true});
async function startHudPilot(page){
 await page.keyboard.up('ArrowUp');
 await page.evaluate(()=>{
  const keys=new Set();window.__hudPilot={fired:false,samples:[]};
  function key(code,held){if(keys.has(code)===held)return;window.dispatchEvent(new KeyboardEvent(held?'keydown':'keyup',{code,bubbles:true,cancelable:true}));if(held)keys.add(code);else keys.delete(code);}
  function tick(){const get=id=>document.getElementById(id),phase=get('phaseLabel').textContent,air=phase.includes('倒扣出轨'),h=parseFloat(get('height').textContent),v=parseFloat(get('descent').textContent),roll=parseInt(get('roll').textContent),terminal=!get('overlay').hidden;
   if(terminal){for(const code of [...keys])key(code,false);return;}
   const fire=air&&roll<14&&v>Math.sqrt(10*h+4);key('KeyE',air);key('ArrowUp',air?fire:phase.includes('加速')||phase.includes('翻转')||phase.includes('回转'));
   if(fire)window.__hudPilot.fired=true;window.__hudPilot.samples.push({phase,h,v,roll,fire});requestAnimationFrame(tick);
  }requestAnimationFrame(tick);
 });
}
await page.locator('#start').click();await page.keyboard.down('ArrowUp');await page.waitForFunction(()=>document.querySelector('#phaseLabel').textContent.includes('螺旋翻转'),{},{timeout:40000});await page.waitForFunction(()=>parseInt(document.querySelector('#roll').textContent)>75,{},{timeout:20000});await startHudPilot(page);await page.locator('#gameShell').screenshot({path:'work/screenshots/02-corkscrew.png'});
await page.waitForFunction(()=>document.querySelector('#phaseLabel').textContent.includes('倒扣出轨'),{},{timeout:20000});await page.locator('#gameShell').screenshot({path:'work/screenshots/03-inverted.png'});
await page.waitForFunction(()=>window.__hudPilot.fired||!document.querySelector('#overlay').hidden,{},{timeout:45000});if(await page.evaluate(()=>window.__hudPilot.fired))await page.locator('#gameShell').screenshot({path:'work/screenshots/04-jet-recovery.png'});
await page.waitForFunction(()=>!document.querySelector('#overlay').hidden,{},{timeout:45000});let terminal=await page.locator('#overlayTitle').textContent();console.log('BROWSER PILOT',terminal,await page.locator('#overlayText').textContent());await page.screenshot({path:'work/screenshots/05-result.png',fullPage:true});assert.match(terminal,/落稳了/,'real browser pilot completes course');assert.match(await page.locator('#best').textContent(),/PTS/,'record saved');
await page.reload({waitUntil:'networkidle'});assert.match(await page.locator('#best').textContent(),/PTS/,'record persists after reload');await page.locator('#start').click();await page.keyboard.down('ArrowUp');await page.waitForTimeout(500);await page.locator('#pause').click();const speed=await page.locator('#speed').textContent();await page.waitForTimeout(300);assert.equal(await page.locator('#speed').textContent(),speed,'pause holds simulation');await page.locator('#start').click();await page.keyboard.up('ArrowUp');await page.locator('#restart').click();assert.match(await page.locator('#overlayTitle').textContent(),/把世界/,'restart returns to starting grid');
await page.locator('.mission').nth(3).click();assert.equal(await page.locator('#levelName').textContent(),'回头半环');assert.match(await page.locator('#overlayText').textContent(),/向左/);assert.equal(await page.locator('.mission').count(),4);
await page.waitForTimeout(1800);await page.screenshot({path:'work/screenshots/08-halfloop-map.png',fullPage:true});
await page.locator('#start').click();await page.locator('#camera').click();await page.waitForTimeout(1800);await page.locator('#gameShell').screenshot({path:'work/screenshots/08b-halfloop-overview.png'});await page.locator('#camera').click();await page.keyboard.down('ArrowUp');await page.waitForFunction(()=>document.querySelector('#phaseLabel').textContent.includes('半环回转'),{},{timeout:40000});await page.waitForFunction(()=>parseInt(document.querySelector('#roll').textContent)>75,{},{timeout:20000});await startHudPilot(page);await page.locator('#gameShell').screenshot({path:'work/screenshots/09-halfloop-climb.png'});
await page.waitForFunction(()=>parseInt(document.querySelector('#roll').textContent)>178,{},{timeout:20000});await page.locator('#gameShell').screenshot({path:'work/screenshots/10-halfloop-upper.png'});
await page.waitForFunction(()=>document.querySelector('#phaseLabel').textContent.includes('倒扣出轨'),{},{timeout:20000});assert.ok(parseInt(await page.locator('#speed').textContent())>0,'leftward speed displays positive');await page.locator('#gameShell').screenshot({path:'work/screenshots/11-halfloop-inverted.png'});
await page.waitForFunction(()=>window.__hudPilot.fired||!document.querySelector('#overlay').hidden,{},{timeout:45000});if(await page.evaluate(()=>window.__hudPilot.fired))await page.locator('#gameShell').screenshot({path:'work/screenshots/12-halfloop-recovery.png'});
await page.waitForFunction(()=>!document.querySelector('#overlay').hidden,{},{timeout:45000});terminal=await page.locator('#overlayTitle').textContent();console.log('HALF LOOP BROWSER PILOT',terminal,await page.locator('#overlayText').textContent());await page.screenshot({path:'work/screenshots/13-halfloop-result.png',fullPage:true});assert.match(terminal,/落稳了/,'real browser pilot completes leftward half-loop map');
await page.locator('.mission').nth(0).click();await page.locator('.mission').nth(3).click();assert.equal(await page.locator('#renderError').isVisible(),false,'switching map geometry retains working renderer');
const mobile=await browser.newContext({viewport:{width:430,height:932},isMobile:true,hasTouch:true,deviceScaleFactor:1});const phone=await mobile.newPage();phone.on('pageerror',e=>errors.push(e.message));await phone.goto('http://127.0.0.1:8765/?map=4',{waitUntil:'networkidle'});assert.equal(await phone.locator('#levelName').textContent(),'回头半环','direct map link selects fourth course');assert.equal(await phone.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true,'mobile no horizontal overflow');console.log('MOBILE INPUT',await phone.evaluate(()=>({coarse:matchMedia('(pointer:coarse)').matches,touch:navigator.maxTouchPoints})));await phone.screenshot({path:'work/screenshots/06-mobile.png',fullPage:true});await phone.locator('#start').click();const gas=await phone.locator('[data-control="gas"]').boundingBox(),assist=await phone.locator('[data-control="assist"]').boundingBox();assert.ok(gas&&assist,'touch controls visible');const cdp=await mobile.newCDPSession(phone);await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:gas.x+gas.width/2,y:gas.y+gas.height/2,id:1},{x:assist.x+assist.width/2,y:assist.y+assist.height/2,id:2}]});await phone.waitForTimeout(600);assert.equal(await phone.locator('.touch-controls .pressed').count(),2,'multi-touch gas and assist both held');assert.ok(parseInt(await phone.locator('#speed').textContent())>0,'touch throttle accelerates');await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});assert.equal(await phone.locator('.touch-controls .pressed').count(),0,'touch release clears both');await phone.locator('#pause').click();await phone.setViewportSize({width:932,height:430});await phone.screenshot({path:'work/screenshots/07-mobile-landscape.png',fullPage:true});
assert.deepEqual(errors,[],'no browser JavaScript errors');console.log('PASS WebGL desktop, corkscrew and half-loop gameplay, pause, restart, persistence, phone layout and multi-touch');await browser.close();})().catch(e=>{console.error(e);process.exit(1);});
